INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0201','数学','3','unit-rate','1','checked','cmath-pilot-v1','{"id":"cmath-dev-0201","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"unit-rate","tags":["归一与平均分"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":1,"questionType":"application","text":"小猴摘了84个桃子，平均分给6只猴子，每只猴子能吃到几个桃子？","numericAnswer":"14","unit":"个","answer":"14（个）","analysis":"平均分给6只猴子，用桃子总数除以猴子只数。\n计算：(84 ÷ 6) = 14（个）。","proof":["/",84,6],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L201","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0202','数学','3','unit-rate','2','checked','cmath-pilot-v1','{"id":"cmath-dev-0202","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"unit-rate","tags":["归一与平均分"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":2,"questionType":"application","text":"李师傅4天加工40个零件，照这样计算，今年4月份全月一共可加工多少个零件？","numericAnswer":"300","unit":"个","answer":"300（个）","analysis":"先求每天加工的零件数；四月有30天，再乘30。\n计算：((40 ÷ 4) × 30) = 300（个）。","proof":["*",["/",40,4],30],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L202","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0204','数学','3','unit-rate','1','checked','cmath-pilot-v1','{"id":"cmath-dev-0204","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"unit-rate","tags":["归一与平均分"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":1,"questionType":"application","text":"做一套校服用布3米。66米布最多能做多少套？","numericAnswer":"22","unit":"套","answer":"22（套）","analysis":"用布的总长度除以每套校服用布的长度。\n计算：(66 ÷ 3) = 22（套）。","proof":["/",66,3],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L204","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0206','数学','3','unit-rate','2','checked','cmath-pilot-v1','{"id":"cmath-dev-0206","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"unit-rate","tags":["归一与平均分"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":2,"questionType":"application","text":"食堂运来一批蔬菜，原计划每天吃45千克，10天可以消费完这批蔬菜，后来根据大家意见，每天比原计划多吃5千克，这批蔬菜可以吃多少天？","numericAnswer":"9","unit":"天","answer":"9（天）","analysis":"先求这批蔬菜的总量，再除以调整后的每天用量。\n计算：((45 × 10) ÷ (45 + 5)) = 9（天）。","proof":["/",["*",45,10],["+",45,5]],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L206","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0207','数学','3','mass','1','checked','cmath-pilot-v1','{"id":"cmath-dev-0207","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"mass","tags":["质量单位换算"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":1,"questionType":"application","text":"菜店运来6吨大白菜，上午卖出3000千克，下午全部卖完．下午卖出大白菜多少千克？","numericAnswer":"3000","unit":"千克","answer":"3000（千克）","analysis":"先把6吨换算为6000千克，再减去上午卖出的质量。\n计算：(6000 − 3000) = 3000（千克）。","proof":["-",6000,3000],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L207","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0208','数学','3','unit-rate','2','checked','cmath-pilot-v1','{"id":"cmath-dev-0208","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"unit-rate","tags":["归一与平均分"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":2,"questionType":"application","text":"李师傅加工490个零件，前5天共加工了350个零件，照这样计算，这批零件共需要多少天能加工完？","numericAnswer":"7","unit":"天","answer":"7（天）","analysis":"先求每天加工的数量，再用总数量除以每天加工量；题目问总天数。\n计算：(490 ÷ (350 ÷ 5)) = 7（天）。","proof":["/",490,["/",350,5]],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L208","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0209','数学','3','integer','1','checked','cmath-pilot-v1','{"id":"cmath-dev-0209","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"integer","tags":["整数四则应用"],"prerequisites":[],"methods":["arithmetic"],"difficulty":1,"questionType":"application","text":"“金秋”体育节的检阅方队中，每班36人，某小学有71个班，一共有多少人参加检阅？","numericAnswer":"2556","unit":"人","answer":"2556（人）","analysis":"每班人数相同，用每班人数乘班级数。\n计算：(36 × 71) = 2556（人）。","proof":["*",36,71],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L209","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0210','数学','3','unit-rate','3','checked','cmath-pilot-v1','{"id":"cmath-dev-0210","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"unit-rate","tags":["归一与平均分"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":3,"questionType":"application","text":"小豪家有个书架共5层，每层放36本书，现在要空出两层放碟片，把这些书放入3层中，每层比原来多放多少本？","numericAnswer":"24","unit":"本","answer":"24（本）","analysis":"先求书的总数，再求改放3层后每层本数，最后减去原来每层本数。\n计算：(((5 × 36) ÷ 3) − 36) = 24（本）。","proof":["-",["/",["*",5,36],3],36],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L210","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0212','数学','3','integer','2','checked','cmath-pilot-v1','{"id":"cmath-dev-0212","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"integer","tags":["整数四则应用"],"prerequisites":[],"methods":["arithmetic"],"difficulty":2,"questionType":"application","text":"停车场上停放着5辆面包车，停放的轿车数量是面包车的4倍。停车场上一共停放着多少辆轿车和面包车？","numericAnswer":"25","unit":"辆","answer":"25（辆）","analysis":"先求轿车数量，再加上面包车数量。\n计算：(5 + (5 × 4)) = 25（辆）。","proof":["+",5,["*",5,4]],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L212","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0213','数学','3','area','1','checked','cmath-pilot-v1','{"id":"cmath-dev-0213","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"area","tags":["长方形与正方形面积"],"prerequisites":["integer"],"methods":["arithmetic"],"difficulty":1,"questionType":"application","text":"某荔枝园有一块长方形的果园，长16米，宽7米。这块荔枝园的面积是多少平方米？","numericAnswer":"112","unit":"平方米","answer":"112（平方米）","analysis":"长方形面积等于长乘宽。\n计算：(16 × 7) = 112（平方米）。","proof":["*",16,7],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L213","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0214','数学','3','integer','1','checked','cmath-pilot-v1','{"id":"cmath-dev-0214","subject":"数学","stage":"primary","grade":3,"sourceGrade":3,"term":"通用","knowledgeId":"integer","tags":["整数四则应用"],"prerequisites":[],"methods":["arithmetic"],"difficulty":1,"questionType":"application","text":"王叔叔和他的爸爸、妈妈去风景区游玩。如果风景区的每张门票售价是108元，王叔叔买所有人的门票一共应付多少钱？","numericAnswer":"324","unit":"元","answer":"324（元）","analysis":"王叔叔和爸爸、妈妈共3人，每人买一张门票。\n计算：(108 × 3) = 324（元）。","proof":["*",108,3],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L214","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
INSERT OR IGNORE INTO bank_questions(id,subject,grade,knowledge_id,difficulty,review_status,batch,payload) VALUES('cmath-dev-0216','数学','4','distance','2','checked','cmath-pilot-v1','{"id":"cmath-dev-0216","subject":"数学","stage":"primary","grade":4,"sourceGrade":3,"term":"通用","knowledgeId":"distance","tags":["路程、速度与时间"],"prerequisites":["unit-rate"],"methods":["arithmetic"],"difficulty":2,"questionType":"application","text":"阿亮7：35从家步行上学，7：44到达学校。他家到学校的距离是306米。阿亮每分钟走多少米？","numericAnswer":"34","unit":"米/分钟","answer":"34（米/分钟）","analysis":"7时35分到7时44分共9分钟，用路程除以时间求每分钟走的距离。\n计算：(306 ÷ (44 − 35)) = 34（米/分钟）。","proof":["/",306,["-",44,35]],"source":"CMATH","originUrl":"https://github.com/XiaoMi/cmath/blob/9fa13ef0b2d03f5a18c1ace7001248d3981d65ea/datasets/cmath_dev.jsonl#L216","license":"CC BY 4.0","attribution":"Tianwen Wei, Jian Luan, Wei Liu, Shuang Dong, Bin Wang — CMATH (2023)","modifications":"补充解析、算式复核、知识点与难度；适用年级为保守映射，未核对江苏具体教材章节。","reviewStatus":"checked","reviewMethod":"source-answer-and-arithmetic-proof","teacherReviewed":false,"batch":"cmath-pilot-v1"}');
